import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// Cross-origin isolation, so the ONNX runtime can use multithreaded WASM
// (SharedArrayBuffer). Render serves the same headers in production.
const isolationHeaders = {
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Cross-Origin-Embedder-Policy': 'require-corp',
}

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  server: { headers: isolationHeaders },
  preview: { headers: isolationHeaders },
})

// App-level state: which screen is showing and what the candidate chose.
// Screens are switched here rather than by URL; there is nothing to link to
// inside an interview.

export type Mode = 'light' | 'heavy'
export type Screen = 'home' | 'setup' | 'interview' | 'report'

export type AppState = {
  screen: Screen
  mode: Mode | null
}

export type AppAction =
  | { type: 'chooseMode'; mode: Mode }
  | { type: 'startInterview' }
  | { type: 'finishInterview' }
  | { type: 'practiseAgain' }
  | { type: 'goHome' }

export const initialState: AppState = { screen: 'home', mode: null }

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'chooseMode':
      return { ...state, mode: action.mode, screen: 'setup' }
    case 'startInterview':
      return state.mode ? { ...state, screen: 'interview' } : state
    case 'finishInterview':
      return { ...state, screen: 'report' }
    case 'practiseAgain':
      return { ...state, screen: 'setup' }
    case 'goHome':
      return { ...state, screen: 'home' }
  }
}

import { useEffect, useRef, type ReactNode } from 'react'

// Every screen starts with its heading, and focus moves to it when the screen
// appears, so keyboard and screen reader users land at the top of the new
// screen instead of on a button that no longer exists.
export function ScreenFrame({ title, children }: { title: string; children: ReactNode }) {
  const headingRef = useRef<HTMLHeadingElement>(null)

  useEffect(() => {
    headingRef.current?.focus()
  }, [])

  return (
    <section className="screen" aria-labelledby="screen-title">
      <h1 id="screen-title" ref={headingRef} tabIndex={-1}>
        {title}
      </h1>
      {children}
    </section>
  )
}

// Shown on every screen (UX.md: privacy). Keep it true: if anything the
// candidate says ever goes over the network, this wording has to change.
export function PrivacyNote() {
  return (
    <p className="privacy-note">
      Everything runs in this browser. What you say never leaves this device; the
      only download is the models, the first time.
    </p>
  )
}

import { useReducer } from 'react'
import { appReducer, initialState } from './app/state'
import { PrivacyNote } from './components/PrivacyNote'
import { Home } from './screens/Home'
import { Interview } from './screens/Interview'
import { Report } from './screens/Report'
import { Setup } from './screens/Setup'

function App() {
  const [state, dispatch] = useReducer(appReducer, initialState)

  return (
    <div className="app">
      <main>
        {state.screen === 'home' && (
          <Home onChooseMode={(mode) => dispatch({ type: 'chooseMode', mode })} />
        )}
        {state.screen === 'setup' && state.mode && (
          <Setup
            mode={state.mode}
            onStart={() => dispatch({ type: 'startInterview' })}
            onBack={() => dispatch({ type: 'goHome' })}
          />
        )}
        {state.screen === 'interview' && (
          <Interview onEnd={() => dispatch({ type: 'finishInterview' })} />
        )}
        {state.screen === 'report' && (
          <Report
            onPractiseAgain={() => dispatch({ type: 'practiseAgain' })}
            onHome={() => dispatch({ type: 'goHome' })}
          />
        )}
      </main>
      <footer>
        <PrivacyNote />
      </footer>
    </div>
  )
}

export default App

