// App-level state: which screen is showing and what the candidate chose.
// Screens are switched here rather than by URL; there is nothing to link to
// inside an interview.

export type Mode = 'light' | 'heavy'
// How the interviewer appears. Same interview either way; only the display
// changes. 'video' shows the 3D avatar, 'phone' is voice only.
export type Display = 'video' | 'phone'
export type Screen = 'home' | 'setup' | 'interview' | 'report'

export type AppState = {
  screen: Screen
  mode: Mode | null
  display: Display
}

export type AppAction =
  | { type: 'chooseMode'; mode: Mode }
  | { type: 'chooseDisplay'; display: Display }
  | { type: 'startInterview' }
  | { type: 'finishInterview' }
  | { type: 'practiseAgain' }
  | { type: 'goHome' }

export const initialState: AppState = { screen: 'home', mode: null, display: 'video' }

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'chooseMode':
      return { ...state, mode: action.mode, screen: 'setup' }
    case 'chooseDisplay':
      return { ...state, display: action.display }
    case 'startInterview':
      return state.mode ? { ...state, screen: 'interview' } : state
    case 'finishInterview':
      return { ...state, screen: 'report' }
    case 'practiseAgain':
      return { ...state, screen: 'setup' }
    case 'goHome':
      return { ...state, screen: 'home' }
  }
}

// Video interview display. Loaded with React.lazy, so three.js and the avatar
// only download when the candidate picks the video interview. Placeholder
// (step 0.2); step 2.1 renders the avatar here, still for reduced motion.
export default function AvatarStage() {
  return (
    <div className="stage stage-video" aria-hidden="true">
      <p className="placeholder">Avatar (step 2.1)</p>
    </div>
  )
}

// Phone screen display: voice only, no three.js. Placeholder (step 0.2);
// step 2.1 adds a calm level indicator driven by the hook's audio level.
export function PhoneStage() {
  return (
    <div className="stage stage-phone" aria-hidden="true">
      <p className="placeholder">Voice only</p>
    </div>
  )
}

