/* Calm and plain, like a real interview room (UX.md). */

:root {
  --bg: #f7f6f3;
  --surface: #ffffff;
  --text: #1f2328;
  --muted: #5b616b;
  --border: #dcd9d2;
  --accent: #2f5d8a;
  --accent-text: #ffffff;
  --focus: #1a73e8;

  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  font: 17px/1.55 var(--sans);
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #17191c;
    --surface: #1f2226;
    --text: #e8e6e3;
    --muted: #a4a9b0;
    --border: #33373d;
    --accent: #7fa8d1;
    --accent-text: #10161c;
    --focus: #8ab4f8;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.app {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  max-width: 880px;
  margin: 0 auto;
  padding: 32px 16px 16px;
}

main {
  flex: 1;
}

footer {
  border-top: 1px solid var(--border);
  margin-top: 32px;
  padding-top: 12px;
}

h1 {
  font-size: 1.9rem;
  font-weight: 600;
  margin: 0 0 16px;
}

h1:focus {
  outline: none;
}

h2,
legend {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0 0 8px;
  padding: 0;
}

p {
  margin: 0 0 8px;
}

.lede {
  color: var(--muted);
  font-size: 1.1rem;
  margin-bottom: 24px;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px 20px;
  margin: 0 0 16px;
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.privacy-note {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

/* Controls */

button {
  font: inherit;
  border-radius: 6px;
  padding: 10px 18px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 16px;
}

/* Home: mode choice */

.mode-options {
  display: grid;
