// App-level state: which screen is showing and what the candidate chose.
// Screens are switched here rather than by URL; there is nothing to link to
// inside an interview.

export type Mode = 'light' | 'heavy'
// How the interviewer appears. Same interview either way; only the display
// changes. 'video' shows the 3D avatar, 'phone' is voice only.
export type Display = 'video' | 'phone'
export type Screen = 'home' | 'setup' | 'interview' | 'report'

export type AppState = {
  screen: Screen
  mode: Mode | null
  // Null until picked on the setup screen. Picking it starts loading the
  // models, and it cannot change after that (UX.md: downloads).
  display: Display | null
}

export type AppAction =
  | { type: 'chooseMode'; mode: Mode }
  | { type: 'chooseDisplay'; display: Display }
  | { type: 'startInterview' }
  | { type: 'finishInterview' }
  | { type: 'practiseAgain' }
  | { type: 'goHome' }

export const initialState: AppState = { screen: 'home', mode: null, display: null }

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'chooseMode':
      return { ...state, mode: action.mode, display: null, screen: 'setup' }
    case 'chooseDisplay':
      return state.display ? state : { ...state, display: action.display }
    case 'startInterview':
      return state.mode && state.display ? { ...state, screen: 'interview' } : state
    case 'finishInterview':
      return { ...state, screen: 'report' }
    case 'practiseAgain':
      return { ...state, display: null, screen: 'setup' }
    case 'goHome':
      return { ...state, display: null, screen: 'home' }
  }
}

// The voice engine (react-ai-voice-avatar) owns its workers and kills them on
// unmount, so it is mounted once, from the display choice until the interview
// ends, and the screens change around it.
export function isEngineMounted(state: AppState): state is AppState & { display: Display; mode: Mode } {
  return (
    state.display !== null &&
    state.mode !== null &&
    (state.screen === 'setup' || state.screen === 'interview')
  )
}

import { lazy, Suspense } from 'react'
import type { Display, Mode } from '../app/state'
import { PhoneEngine } from './PhoneEngine'

// Only fetched when the candidate picks the video interview, so three.js and
// the avatar never load for a phone screen.
const VideoEngine = lazy(() => import('./VideoEngine'))

// The one place the voice engine lives. App mounts it once, at a fixed spot in
// its tree, from the display choice on the setup screen until the interview
// ends; it is hidden on setup (loading in the background) and shown as the
// stage on the interview screen. Both engines get the same interview logic;
// only what they draw differs. Placeholders until step 2.1.
export function EngineHost({ display, mode, visible }: { display: Display; mode: Mode; visible: boolean }) {
  return (
    <div className="engine-host" hidden={!visible}>
      {display === 'video' ? (
        <Suspense fallback={<div className="stage stage-video" aria-hidden="true" />}>
          <VideoEngine mode={mode} />
        </Suspense>
      ) : (
        <PhoneEngine mode={mode} />
      )}
    </div>
  )
}

import type { Mode } from '../app/state'

// Video interview: <AiVoiceAvatar> runs the engine and draws the avatar.
// Default export for React.lazy. Placeholder (step 0.2); step 2.1 renders the
// avatar here, still for reduced motion.
export default function VideoEngine({ mode }: { mode: Mode }) {
  return (
    <div className="stage stage-video" aria-hidden="true" data-mode={mode}>
      <p className="placeholder">Avatar (step 2.1)</p>
    </div>
  )
}

import type { Mode } from '../app/state'

// Phone screen: the headless hook (react-ai-voice-avatar/headless) runs the
// engine, no three.js. Placeholder (step 0.2); step 2.1 adds the hook and a
// calm level indicator driven by its audio level.
export function PhoneEngine({ mode }: { mode: Mode }) {
  return (
    <div className="stage stage-phone" aria-hidden="true" data-mode={mode}>
      <p className="placeholder">Voice only</p>
    </div>
  )
}

import { useReducer } from 'react'
import { appReducer, initialState, isEngineMounted } from './app/state'
import { PrivacyNote } from './components/PrivacyNote'
import { EngineHost } from './engine/EngineHost'
import { Home } from './screens/Home'
import { Interview } from './screens/Interview'
import { Report } from './screens/Report'
import { Setup } from './screens/Setup'

function App() {
  const [state, dispatch] = useReducer(appReducer, initialState)

  return (
    <div className={`app app--${state.screen}`}>
      <main>
        {state.screen === 'home' && (
          <Home onChooseMode={(mode) => dispatch({ type: 'chooseMode', mode })} />
        )}
        {state.screen === 'setup' && state.mode && (
          <Setup
            mode={state.mode}
            display={state.display}
            onChooseDisplay={(display) => dispatch({ type: 'chooseDisplay', display })}
            onStart={() => dispatch({ type: 'startInterview' })}
            onBack={() => dispatch({ type: 'goHome' })}
          />
        )}
        {state.screen === 'interview' && state.display && (
          <Interview
            display={state.display}
            onEnd={() => dispatch({ type: 'finishInterview' })}
          />
        )}
        {state.screen === 'report' && (
          <Report
            onPractiseAgain={() => dispatch({ type: 'practiseAgain' })}
            onHome={() => dispatch({ type: 'goHome' })}
          />
        )}
      </main>

      {/* Same position in the tree on setup and interview, so changing screen
          never remounts the engine (and never kills its workers). */}
      {isEngineMounted(state) && (
        <EngineHost
          display={state.display}
          mode={state.mode}
          visible={state.screen === 'interview'}
        />
      )}

      <footer>
        <PrivacyNote />
      </footer>
    </div>
  )
}

export default App

