/* Calm, premium, dark: a quiet interview room (UX.md: look and feel). */

:root {
  /* Background */
  --bg: #0e1117;
  --bg-gradient:
    radial-gradient(1200px 700px at 15% -10%, #1e2a44 0%, transparent 60%),
    radial-gradient(900px 600px at 110% 20%, #23203d 0%, transparent 55%),
    linear-gradient(180deg, #10141c 0%, #0b0e13 100%);

  /* Glass: dark enough that text keeps AA contrast whatever is behind it. */
  --glass-bg: rgba(22, 27, 37, 0.72);
  --glass-border: rgba(255, 255, 255, 0.09);
  --glass-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
  --glass-blur: 18px;
  --solid-panel: #161b25;

  /* Plain surfaces inside glass */
  --surface: rgba(255, 255, 255, 0.04);
  --surface-hover: rgba(255, 255, 255, 0.07);
  --border: rgba(255, 255, 255, 0.1);

  /* Text */
  --text: #e9ecf2;
  --muted: #a3acbc;

  /* The one accent colour */
  --accent: #8fb4ff;
  --accent-text: #0d1320;
  --accent-soft: rgba(143, 180, 255, 0.14);

  /* Radius scale: the only radius values in the app */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-pill: 999px;

  --ease: 160ms ease;
  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;

  font: 17px/1.55 var(--sans);
  color-scheme: dark;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100svh;
  background: var(--bg-gradient);
  background-attachment: fixed;
}

/* Layout */

.app {
  min-height: 100svh;
  display: grid;
  grid-template-areas:
    'main'
    'footer';
  grid-template-rows: 1fr auto;
  gap: 24px;
  max-width: 880px;
  margin: 0 auto;
  padding: 32px 16px 16px;
}

main {
  grid-area: main;
  min-width: 0;
}

footer {
  grid-area: footer;
  padding: 0 4px;
}

/* Interview: the engine's stage sits beside the screen. */
.app--interview {
  max-width: 1120px;
  grid-template-areas:
    'stage main'
    'footer footer';
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  grid-template-rows: 1fr auto;
  align-items: start;
}

@media (max-width: 760px) {
  .app--interview {
    grid-template-areas:
      'stage'
      'main'
      'footer';
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }
}

.engine-host {
  grid-area: stage;
  min-width: 0;
}

.engine-host[hidden] {
  display: none;
}

/* Glass: only on the few big panels that carry the .glass class. */

.glass {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--glass-shadow);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(120%);
  backdrop-filter: blur(var(--glass-blur)) saturate(120%);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .glass {
    background: var(--solid-panel);
  }
}

@media (prefers-reduced-transparency: reduce) {
  .glass {
    background: var(--solid-panel);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

.screen {
  padding: 28px 28px 24px;
  animation: screen-in var(--ease);
}

@keyframes screen-in {
  from {
    opacity: 0;
  }
}

/* Type */

h1 {
  font-size: 1.85rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 0 0 12px;
}

h2,
legend {
  font-size: 1.05rem;
  font-weight: 600;
  margin: 0 0 6px;
  padding: 0;
}

h1:focus,
h2:focus {
  outline: none;
}

p {
  margin: 0 0 8px;
}

.lede {
  color: var(--muted);
  font-size: 1.08rem;
  margin-bottom: 24px;
}

.muted {
  color: var(--muted);
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.privacy-note {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

/* Plain surfaces inside the glass panel: no blur. */

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px 18px;
  margin: 0 0 14px;
}

/* Controls */

button {
  font: inherit;
  font-weight: 500;
  border-radius: var(--radius-md);
  padding: 10px 18px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  transition:
    background-color var(--ease),
    border-color var(--ease),
    opacity var(--ease);
}

button:hover {
  background: var(--surface-hover);
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}

button.primary:hover {
  opacity: 0.9;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

input[type='radio'] {
  accent-color: var(--accent);
  width: 18px;
  height: 18px;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 18px;
}

/* Home: mode choice */

.mode-options {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  margin: 12px 0;
}

.mode-option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  text-align: left;
  padding: 16px 18px;
}

.mode-option:hover {
  border-color: var(--accent);
}

.mode-name,
.choice-name {
  font-weight: 600;
  display: block;
}

.mode-detail,
.choice-detail {
  color: var(--muted);
  font-size: 0.95rem;
  display: block;
}

/* Setup: radio choices */

.choice-group {
  display: grid;
  gap: 6px;
  min-width: 0;
  border: 0;
  margin: 0 0 8px;
  padding: 0;
}

/* Keep the legend in the flow instead of on a border. */
.choice-group legend {
  float: left;
  width: 100%;
  margin-bottom: 6px;
}

.choice {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition:
    background-color var(--ease),
    border-color var(--ease);
}

.choice:hover {
  background: var(--surface-hover);
}

.choice:has(input:checked) {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.choice input {
  margin-top: 3px;
  flex: none;
}

/* Interview */

.stage {
  aspect-ratio: 3 / 4;
  background: var(--solid-panel);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--glass-shadow);
  display: grid;
  place-items: center;
  overflow: hidden;
}

.stage-phone {
  aspect-ratio: 1;
}

.state {
  display: inline-block;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: var(--radius-pill);
  padding: 3px 14px;
  margin-bottom: 12px;
}

.label {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin: 18px 0 4px;
}

.question {
  font-size: 1.25rem;
  line-height: 1.45;
}

.interview-controls {
  justify-content: flex-start;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

